1	import type { Cents } from "./money"
2	import type { Order } from "./order"
3	
4	export interface DayReport {
5	    day: string
6	    orders: number
7	    revenue: Cents
8	}
9	
10	/*  what the orders of a list brought in  */
11	export function revenue(orders: Order[]): Cents {
12	    let sum = 0
13	    for (const order of orders)
14	        if (order.status === "paid")
15	            sum += order.total
16	    return sum
17	}
18	
19	/*  number of orders per status, for the dashboard  */
20	export function countByStatus(orders: Order[]): Map<string, number> {
21	    const counts = new Map<string, number>()
22	    for (const order of orders)
23	        counts.set(order.status, (counts.get(order.status) ?? 0) + 1)
24	    return counts
25	}
26	
27	/*  one line per day on which orders were placed, oldest day first  */
28	export function dailyReport(orders: Order[]): DayReport[] {
29	    const days = new Map<string, Order[]>()
30	    for (const order of orders) {
31	        const list = days.get(order.placedOn) ?? []
32	        list.push(order)
33	        days.set(order.placedOn, list)
34	    }
35	    return [...days.keys()].sort().map((day) => {
36	        const list = days.get(day) ?? []
37	        return { day, orders: list.length, revenue: revenue(list) }
38	    })
39	}
