1	import { formatAmount } from "./money"
2	import type { Order } from "./order"
3	import type { Refund } from "./refund"
4	import type { ReturnLine } from "./returns"
5	
6	export interface Mail {
7	    to: string
8	    subject: string
9	    html: string
10	}
11	
12	const outbox: Mail[] = []
13	
14	export function escapeHtml(text: string): string {
15	    return text
16	        .replace(/&/g, "&amp;")
17	        .replace(/</g, "&lt;")
18	        .replace(/>/g, "&gt;")
19	        .replace(/"/g, "&quot;")
20	}
21	
22	/*  confirmation mail; the discount code is the one the customer typed into the order form  */
23	export function renderConfirmation(order: Order, code: string | undefined): string {
24	    const lines = [
25	        `<h1>Thank you for your order</h1>`,
26	        `<p>Order ${escapeHtml(order.id)} for ${escapeHtml(order.customer.email)} is confirmed.</p>`
27	    ]
28	    if (code !== undefined)
29	        lines.push(`<p>Your code ${escapeHtml(code)} was applied.</p>`)
30	    return lines.join("\n")
31	}
32	
33	/*  what came back and what is paid back for it  */
34	function renderReturnConfirmation(order: Order, lines: ReturnLine[], refund: Refund): string {
35	    const rows = lines.map((line) => `<li>${line.quantity} x ${line.sku}</li>`)
36	    const target = refund.method === "credit" ? "as store credit" : "to your payment method"
37	    return [
38	        `<h1>We received your return</h1>`,
39	        `<p>Order ${escapeHtml(order.id)}:</p>`,
40	        `<ul>${rows.join("")}</ul>`,
41	        `<p>${formatAmount(refund.amount)} will be paid back ${target}.</p>`
42	    ].join("\n")
43	}
44	
45	export function outboxSize(): number {
46	    return outbox.length
47	}
48	
49	/*  the mails waiting to be sent, oldest first  */
50	export function queuedMails(): readonly Mail[] {
51	    return outbox
52	}
53	
54	function queueMail(mail: Mail): void {
55	    if (!/^[^@\s]+@[^@\s]+$/.test(mail.to))
56	        throw new Error(`invalid recipient ${mail.to}`)
57	    outbox.push(mail)
58	}
59	
60	export async function sendConfirmation(order: Order, code?: string): Promise<void> {
61	    try {
62	        queueMail({
63	            to:      order.customer.email,
64	            subject: `Your order ${order.id}`,
65	            html:    renderConfirmation(order, code)
66	        })
67	    }
68	    catch (err) {
69	        /*  the order is already stored; a bad address must not turn it into a failed order  */
70	        console.error(`mail for ${order.id} not queued`, err)
71	    }
72	}
73	
74	export async function sendReturnConfirmation(order: Order, lines: ReturnLine[], refund: Refund): Promise<void> {
75	    try {
76	        queueMail({
77	            to:      order.id,
78	            subject: `Your return for order ${order.id}`,
79	            html:    renderReturnConfirmation(order, lines, refund)
80	        })
81	    }
82	    catch (err) {
83	        console.error(`mail for the return of ${order.id} not queued`, err)
84	    }
85	}
